    "q": "ข้อใดคือเจตนาของผู้เขียนข้อความต่อไปนี้ ในช่วงฤดูร้อนของประเทศไทยเด็ก ๆ มักจะมีอาการท้องร่วงเฉียบพลันได้บ่อย สาเหตุส่วนใหญ่ของอาการท้องร่วงมักมาจากติด เชื้อแบคทีเรียที่ปนเปื้อนมาจากอาหารและน้ำดื่ม ทำให้มีอาการถ่ายเหลว อาเจียน ส่งผลเสียต่อร่างกายโดยอาจจะทำให้มีการ สูญเสียน้ำและเกลือแร่ ดังนั้นการเฝ้าระวังโรคท้องร่วงในเด็กในช่วงฤดูร้อนจึงเป็นสิ่งที่สำคัญ คุณพ่อคุณแม่ไม่ควรมองข้าม อาการท้องร่วงเฉียบพลันปวดท้องบิดเกร็ง แน่นท้อง คลื่นไส้ อาเจียน มีไข้ท้องเสียเป็นน้ำ เนื้อเหลว ในบางกรณีอาจมีมูก เลือกปนได้มีอาการของการสูญเสียสารน้ำและเกลือแร่ ปากแห้ง อ่อนเพลีย ไม่มีแรง ชีพจรเต้นเร็ว ปัสสาวะออกลดลง การรักษาโรคท้องร่วงเฉียบพลัน สามารถแบ่งได้เป็น ๒ ประเภท ได้แก่ - ผู้ป่วยที่มีอาการไม่รุนแรงผู้ป่วยสามารถดื่มเกลือแร่เพื่อทดแทนน้ำและเกลือแร่ที่สูญเสียไป - ผู้ป่วยที่มีอาการรุนแรงหากร่างกายสูญเสียน้ำและเกลือแร่มากจนเกินไป จากอาการอาเจียนและ ถ่ายเหลว ร่วมกับผู้ป่วยรับประทานอาหารและดื่มน้ำได้น้อย แนะนำพบแพทย์เพื่อประเมินอาการ ในบางรายจำเป็นต้องได้รับสารน้ำทดแทนทางหลอดเลือดและยาปฏิชีวนะเพิ่มเติม",
